"use server";

import mailchimp from "@mailchimp/mailchimp_marketing";

// Initialize Mailchimp with your API key and server prefix
mailchimp.setConfig({
  apiKey: process.env.MAILCHIMP_API_KEY,
  server: process.env.MAILCHIMP_SERVER_PREFIX, // e.g., "us1"
});

interface MailchimpError extends Error {
  response?: {
    body: {
      title: string;
      detail: string;
    };
  };
}

export async function subscribeToNewsletter(formData: FormData) {
  const email = formData.get("email") as string;

  if (!email) {
    return {
      success: false,
      message: "Email is required",
    };
  }

  try {
    // Add member to list
    await mailchimp.lists.addListMember(
      process.env.MAILCHIMP_AUDIENCE_ID as string,
      {
        email_address: email,
        status: "subscribed",
      }
    );
    console.log("Success! You are now subscribed.");
    return {
      success: true,
      message: "Success! You are now subscribed.",
    };
  } catch (error: unknown) {
    const mailchimpError = error as MailchimpError;
    if (mailchimpError.response?.body) {
      const { title, detail } = mailchimpError.response.body;

      if (title && title.includes("Member Exists")) {
        return {
          success: false,
          message: "You are already subscribed to our newsletter.",
        };
      }

      return {
        success: false,
        message:
          detail || title || "An error occurred with the subscription service.",
      };
    }

    return {
      success: false,
      message: "An error occurred. Please try again later.",
    };
  }
}

"use client";

import type React from "react";
import { useState, useEffect } from "react";
import { Icon } from "./icons";
import { cx } from "cva";

interface SearchProps {
  onSearch: (value: string) => void;
  initialValue?: string;
  isSearchOpen?: boolean;
  setIsSearchOpen?: (value: boolean) => void;
}

export default function Search({
  onSearch,
  initialValue = "",
  isSearchOpen,
  setIsSearchOpen,
}: SearchProps) {
  const [searchQuery, setSearchQuery] = useState(initialValue);
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    setIsMounted(true);

    if (typeof window !== "undefined") {
      const urlParams = new URLSearchParams(window.location.search);
      const search = urlParams.get("search") || "";
      setSearchQuery(search);
    }
  }, []);

  useEffect(() => {
    if (initialValue !== searchQuery) {
      setSearchQuery(initialValue);
    }
  }, [initialValue]);

  const handleSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setSearchQuery(value);

    onSearch(value);

    if (isMounted && typeof window !== "undefined") {
      const params = new URLSearchParams(window.location.search);

      if (value) {
        params.set("search", value);
      } else {
        params.delete("search");
      }

      const newUrl = `${window.location.pathname}?${params.toString()}`;
      window.history.pushState({ path: newUrl }, "", newUrl);
    }
  };

  return (
    <>
      <div className="relative border border-black w-full rounded-full overflow-hidden px-4 hidden lg:block">
        <Icon
          name="searchBlack"
          className="size-4 absolute left-4 top-1/2 -translate-y-1/2"
        />
        <input
          type="text"
          placeholder="Search..."
          value={searchQuery}
          onChange={handleSearch}
          className="w-full py-2 label-sm  outline-none pl-6"
        />
      </div>
      <div className=" w-12 h-12 lg:hidden">
        {!isSearchOpen && (
          <button
            className="h-full w-12 bg-black rounded-full z-30 relative flex items-center justify-center"
            onClick={() => setIsSearchOpen?.(true)}
          >
            <Icon name="searchWhite" className="shrink-0" />
          </button>
        )}
        <div
          className={cx(
            "absolute right-4 top-0 w-12 h-full transition-all p-0 rounded-full bg-black duration-300 flex items-center justify-start",
            {
              "w-[calc(100vw-32px)] px-4 py-3": isSearchOpen,
            }
          )}
        >
          <Icon
            name="searchWhite"
            className="size-4 absolute left-4 top-1/2 -translate-y-1/2"
          />
          <input
            type="text"
            placeholder="Search"
            value={searchQuery}
            onChange={handleSearch}
            className={cx(
              "text-white  pl-6 outline-none border-none w-full transition-all duration-300",
              {
                "opacity-0": !isSearchOpen,
              }
            )}
          />
          <button
            className={cx("transition-all duration-300", {
              "opacity-0": !isSearchOpen,
            })}
            onClick={() => {
              setSearchQuery("");

              onSearch("");

              if (typeof window !== "undefined") {
                const params = new URLSearchParams(window.location.search);
                params.delete("search");
                const newUrl = `${window.location.pathname}?${params.toString()}`;
                window.history.pushState({ path: newUrl }, "", newUrl);
              }

              setIsSearchOpen?.(false);
            }}
          >
            <Icon name="closeWhite" />
          </button>
        </div>
      </div>
    </>
  );
}

import { NextResponse } from "next/server";
import mailchimp from "@mailchimp/mailchimp_marketing";

interface MailchimpError extends Error {
  response?: {
    body: {
      title: string;
      detail: string;
      status: number;
    };
  };
}

mailchimp.setConfig({
  apiKey: process.env.MAILCHIMP_API_KEY,
  server: process.env.MAILCHIMP_SERVER_PREFIX,
});

export async function POST(request: Request) {
  try {
    const { email } = await request.json();

    if (!email) {
      return NextResponse.json(
        { message: "Email is required" },
        { status: 400 }
      );
    }

    // Add member to list
    await mailchimp.lists.addListMember(
      process.env.MAILCHIMP_AUDIENCE_ID as string,
      {
        email_address: email,
        status: "subscribed",
      }
    );

    return NextResponse.json(
      { message: "Success! You are now subscribed." },
      { status: 201 }
    );
  } catch (error: unknown) {
    const mailchimpError = error as MailchimpError;
    console.log(mailchimpError);

    if (mailchimpError.response?.body) {
      const { title, detail, status } = mailchimpError.response.body;

      if (status === 400 && title.includes("Member Exists")) {
        return NextResponse.json(
          { message: "You are already subscribed to our newsletter." },
          { status: 400 }
        );
      }

      return NextResponse.json(
        { message: detail || title },
        { status: status || 500 }
      );
    }

    return NextResponse.json(
      { message: "An error occurred. Please try again later." },
      { status: 500 }
    );
  }
}

