"use client";

import GridCard from "@/components/shared/cards/grid-card";
import { useGlobaleContext } from "@/components/globale/globale-context";

export default function Home() {
  const { toolsData, activeTags } = useGlobaleContext();
  return (
    <section className="lg:border border-[#C9C3B9] rounded-lg p-4 lg:p-0 ">
      {toolsData?.domains
        .sort((a, b) => a.level - b.level)
        .map((item) => {
          const hasMatchingTools = item.categories.some((category) => {
            const filteredTools = activeTags.includes("all")
              ? category.tools
              : category.tools.filter((tool) =>
                  tool.tags?.some((tag) => activeTags.includes(tag))
                );
            return filteredTools.length > 0;
          });

          if (item.categories.length === 0 || !hasMatchingTools) return null;

          return (
            <GridCard
              key={item.name}
              categories={item.categories}
              title={item.name}
              description={item.description}
            />
          );
        })}
    </section>
  );
}

export interface Tool {
  name: string;
  description: string;
  date_added: string;
  icon_url: string;
  oss: boolean;
  tags: string[];
  verified: boolean;
  website_url: string;
  popular: boolean;
}

export interface Category {
  description: string;
  level: number;
  name: string;
  tools: Tool[];
}

export interface Domain {
  categories: Category[];
  description: string;
  level: number;
  name: string;
}

export interface ToolsData {
  domains: Domain[];
}

/* eslint-disable @typescript-eslint/no-require-imports */
const fs = require("fs");
const yaml = require("js-yaml");
const path = require("path");

// Path to your YAML file
const yamlFilePath = path.join(process.cwd(), "public", "tools-data.yaml"); // Update with your actual YAML filename
// Path where you want to save the JSON file (in the public directory)
const jsonFilePath = path.join(process.cwd(), "public", "tools-data.json");

try {
  // Make sure the YAML file exists
  if (!fs.existsSync(yamlFilePath)) {
    console.error(`YAML file not found at ${yamlFilePath}`);
    process.exit(1);
  }

  // Read the YAML file
  const yamlContent = fs.readFileSync(yamlFilePath, "utf8");

  // Convert YAML to JSON
  const jsonData = yaml.load(yamlContent);

  // Write the JSON to the public directory
  fs.writeFileSync(jsonFilePath, JSON.stringify(jsonData, null, 2));

  console.log("Successfully converted YAML to JSON");
  console.log(`YAML file: ${yamlFilePath}`);
  console.log(`JSON file: ${jsonFilePath}`);
} catch (error) {
  console.error("Error converting YAML to JSON:", error);
  process.exit(1);
}
